diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..2edfc8d 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,85 @@ export interface Record {
   warns: readonly string[];
 }

+type EntryType = "ruledOut" | "limits" | "warns";
+
+interface Entry {
+  type: EntryType;
+  text: string;
+  group: string;
+}
+
+const classifyEntry = (text: string): string => {
+  const normalized = text.toLowerCase();
+  if (
+    normalized.includes("stateful") ||
+    normalized.includes("infrastructure") ||
+    normalized.includes("always-on") ||
+    normalized.includes("cache") ||
+    normalized.includes("operational") ||
+    normalized.includes("operate")
+  ) {
+    return "no-new-infrastructure";
+  }
+  return "other";
+};
+
+const selectRepresentative = (entries: Entry[]): Entry => {
+  // Prefer "limits" over "ruledOut" (more prescriptive)
+  const limits = entries.filter((e) => e.type === "limits");
+  if (limits.length > 0) {
+    // Within limits, prefer ones with more substance (longer text)
+    return limits.reduce((a, b) => (a.text.length > b.text.length ? a : b));
+  }
+  // Fall back to ruledOut, preferring longer explanations
+  return entries.reduce((a, b) => (a.text.length > b.text.length ? a : b));
+};
+
 export const project = (records: readonly Record[]): string => {
-  const lines: string[] = [];
+  const allEntries: Entry[] = [];
+
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of record.ruledOut)
+      allEntries.push({
+        type: "ruledOut",
+        text: entry,
+        group: classifyEntry(entry),
+      });
+    for (const entry of record.limits)
+      allEntries.push({
+        type: "limits",
+        text: entry,
+        group: classifyEntry(entry),
+      });
+    for (const entry of record.warns)
+      allEntries.push({
+        type: "warns",
+        text: entry,
+        group: classifyEntry(entry),
+      });
+  }
+
+  // Group entries by semantic equivalence
+  const groupedByClass = new Map<string, Entry[]>();
+  for (const entry of allEntries) {
+    if (!groupedByClass.has(entry.group)) {
+      groupedByClass.set(entry.group, []);
+    }
+    groupedByClass.get(entry.group)!.push(entry);
   }
+
+  // Select representative from each group and format output
+  const lines: string[] = [];
+  for (const [group, entries] of groupedByClass) {
+    const representative = selectRepresentative(entries);
+    const typePrefix =
+      representative.type === "ruledOut"
+        ? "ruled out"
+        : representative.type === "limits"
+          ? "limit"
+          : "warn";
+    lines.push(`- ${typePrefix}: ${representative.text}`);
+  }
+
   return lines.join("\n");
 };
